import type {
  BiomeId,
  LayoutTemplate,
  MapObjective,
  TheaterProfile,
  UnitClassId,
  WeatherType,
} from './types';

export interface HistoricalBattleSpec {
  title: string;
  dateStr: string;
  yearStr: string;
  layout: LayoutTemplate;
  biome: BiomeId;
  weather: WeatherType;
  objective: MapObjective;
  theater: TheaterProfile;
  alliedCmdr: string;
  axisCmdr: string;
  bossClass: UnitClassId;
  bossWeaponId: string;
  scale: 'MEDIUM' | 'LARGE' | 'COLOSSAL';
  forceSummary: string;
}

type RawBattleRow = [
  string, // title
  string, // dateStr
  LayoutTemplate,
  BiomeId,
  WeatherType,
  MapObjective,
  TheaterProfile,
  string, // alliedCmdr
  string, // axisCmdr
  UnitClassId,
  string, // bossWeaponId
  'MEDIUM' | 'LARGE' | 'COLOSSAL',
  string // forceSummary
];

function extractYear(dateStr: string): string {
  const m = dateStr.match(/19\d{2}(?:–19\d{2})?/);
  if (m) return m[0];
  const years = dateStr.match(/19\d{2}/g);
  if (years && years.length >= 2 && years[0] !== years[years.length - 1]) {
    return `${years[0]}–${years[years.length - 1]}`;
  }
  return years?.[0] ?? '1914';
}

